// Type-checks every TypeScript code block in the skill against the pinned zod and typescript.
//
// Usage: bun blocks.ts [skill-root] [--json out.json]
//
// Rules the check enforces:
// - Every block compiles under strict mode. No diagnostic code is filtered.
// - A block sees the top-level declarations of the earlier blocks in the same file, as a reader does.
//   Names that no block declares come from prelude.d.ts, which declares each one with a real type.
//   Packages the check does not install are declared in modules.d.ts, with the signatures the examples use.
// - A line that must not compile carries `// @ts-expect-error`. TypeScript reports TS2578 when the line compiles.
// - A deprecated call is allowed only on a line whose comment starts with `deprecated`, and that marker is
//   allowed only on a line with a deprecated call. Both directions fail the check.
// - AGENTS.md and v3/AGENTS.md are skipped when they carry the generated marker, because agents.ts builds
//   them from checked files.
// - A block under v3/ is the Zod 3 form. Its `zod` and `zod/*` imports resolve to the `zod3` alias that
//   package.json pins (npm:zod@3.25.76), so the text stays what a Zod 3 reader copies. `zod/mini` has no
//   Zod 3 target and fails to resolve, as it should.
// - A rule with no v3/rules/<id>.md "applies as written" in a Zod 3 file, so its blocks are compiled against
//   Zod 3 as well. The rules that have no Zod 3 form at all are the ids listed under "## No Zod 3 form" in
//   v3/references/zod-3.md; those are skipped.
import ts from "typescript";
import { existsSync, readdirSync, readFileSync, writeFileSync } from "node:fs";
import { join, resolve } from "node:path";

const CHECK = import.meta.dir;
const args = process.argv.slice(2);
const jsonAt = args.indexOf("--json");
const jsonOut = jsonAt >= 0 ? args[jsonAt + 1] : undefined;
const positional = args.filter((a, i) => !a.startsWith("--") && (jsonAt < 0 || i !== jsonAt + 1));
const ROOT = resolve(positional[0] ?? join(CHECK, "../.."));
export const GENERATED_MARKER = "<!-- Generated by .github/check/agents.ts. Do not edit. -->";

type Block = { src: string; line: number; body: string; tsx: boolean; v3: boolean };
type Finding = { src: string; line: number; code: number | string; msg: string; text: string };

export const isV3 = (src: string) => src.startsWith("v3/");

function markdownFiles(root: string): string[] {
  const list = (d: string) =>
    existsSync(join(root, d))
      ? readdirSync(join(root, d)).filter((f) => f.endsWith(".md")).sort().map((f) => `${d}/${f}`)
      : [];
  const files = ["SKILL.md", ...list("rules"), ...list("references"), ...list("v3/rules"), ...list("v3/references")];
  for (const agents of ["AGENTS.md", "v3/AGENTS.md"]) {
    const path = join(root, agents);
    if (existsSync(path) && !readFileSync(path, "utf8").includes(GENERATED_MARKER)) files.push(agents);
  }
  return files;
}

export function extractBlocks(root: string, src: string): Block[] {
  const lines = readFileSync(join(root, src), "utf8").split("\n");
  const blocks: Block[] = [];
  for (let i = 0; i < lines.length; i++) {
    const open = /^\s*```(ts|typescript|tsx)\s*$/.exec(lines[i]);
    if (!open) continue;
    let j = i + 1;
    while (j < lines.length && !/^\s*```\s*$/.test(lines[j])) j++;
    blocks.push({ src, line: i + 2, body: lines.slice(i + 1, j).join("\n"), tsx: open[1] === "tsx", v3: isV3(src) });
    i = j;
  }
  return blocks;
}

// Names a top-level statement declares, split by the space they occupy.
function declared(stmt: ts.Statement): { values: string[]; types: string[] } {
  const values: string[] = [];
  const types: string[] = [];
  const bindingNames = (n: ts.BindingName): string[] =>
    ts.isIdentifier(n) ? [n.text] : n.elements.flatMap((e) => (ts.isOmittedExpression(e) ? [] : bindingNames(e.name)));
  if (ts.isVariableStatement(stmt)) for (const d of stmt.declarationList.declarations) values.push(...bindingNames(d.name));
  else if (ts.isFunctionDeclaration(stmt) && stmt.name) values.push(stmt.name.text);
  else if ((ts.isClassDeclaration(stmt) || ts.isEnumDeclaration(stmt)) && stmt.name) {
    values.push(stmt.name.text);
    types.push(stmt.name.text);
  } else if (ts.isInterfaceDeclaration(stmt) || ts.isTypeAliasDeclaration(stmt)) types.push(stmt.name.text);
  else if (ts.isModuleDeclaration(stmt) && ts.isIdentifier(stmt.name)) values.push(stmt.name.text);
  else if (ts.isImportDeclaration(stmt) && stmt.importClause) {
    const c = stmt.importClause;
    const names: string[] = [];
    if (c.name) names.push(c.name.text);
    if (c.namedBindings && ts.isNamespaceImport(c.namedBindings)) names.push(c.namedBindings.name.text);
    if (c.namedBindings && ts.isNamedImports(c.namedBindings)) for (const e of c.namedBindings.elements) names.push(e.name.text);
    values.push(...names);
    types.push(...names);
  } else if (ts.isImportEqualsDeclaration(stmt)) values.push(stmt.name.text);
  return { values, types };
}

function isDeclaration(stmt: ts.Statement): boolean {
  return (
    ts.isVariableStatement(stmt) ||
    ts.isFunctionDeclaration(stmt) ||
    ts.isClassDeclaration(stmt) ||
    ts.isEnumDeclaration(stmt) ||
    ts.isInterfaceDeclaration(stmt) ||
    ts.isTypeAliasDeclaration(stmt) ||
    ts.isImportDeclaration(stmt) ||
    ts.isImportEqualsDeclaration(stmt)
  );
}

type Composed = { file: string; text: string; bodyStart: number; block: Block };

// Builds the module for block k: earlier top-level declarations it does not redeclare, then the block itself.
function compose(blocks: Block[], k: number, index: number): Composed {
  const block = blocks[k];
  const parse = (b: Block) => ts.createSourceFile("x.tsx", b.body, ts.ScriptTarget.Latest, true, ts.ScriptKind.TSX);
  const own = parse(block).statements.map(declared);
  const ownValues = new Set(own.flatMap((d) => d.values));
  const ownTypes = new Set(own.flatMap((d) => d.types));
  type Entry = { text: string; values: string[]; types: string[] };
  const context: Entry[] = [];
  for (const prior of blocks.slice(0, k)) {
    for (const stmt of parse(prior).statements) {
      if (!isDeclaration(stmt)) continue;
      const d = declared(stmt);
      if (d.values.length === 0 && d.types.length === 0) continue;
      // Each block chooses its own `z`: a Zod Mini import in one block must not reach the next.
      if (d.values.includes("z")) continue;
      // A later declaration of the same name replaces the earlier one, as it would for a reader.
      for (let i = context.length - 1; i >= 0; i--) {
        const e = context[i];
        if (e.values.some((n) => d.values.includes(n)) || e.types.some((n) => d.types.includes(n))) context.splice(i, 1);
      }
      context.push({ text: stmt.getText(), values: d.values, types: d.types });
    }
  }
  const kept = context.filter((e) => !e.values.some((n) => ownValues.has(n)) && !e.types.some((n) => ownTypes.has(n)));
  const bindsZ = ownValues.has("z") || kept.some((e) => e.values.includes("z"));
  const header = (bindsZ ? "" : 'import * as z from "zod";\n') + kept.map((e) => e.text).join("\n") + "\n";
  const text = `${header}${block.body}\nexport {};\n`;
  const file = join(CHECK, ".blocks", `b${String(index).padStart(4, "0")}.${block.tsx ? "tsx" : "ts"}`);
  return { file, text, bodyStart: header.length, block };
}

const options: ts.CompilerOptions = {
  strict: true,
  noEmit: true,
  skipLibCheck: true,
  target: ts.ScriptTarget.ES2022,
  module: ts.ModuleKind.ESNext,
  moduleResolution: ts.ModuleResolutionKind.Bundler,
  lib: ["lib.es2023.d.ts", "lib.dom.d.ts", "lib.dom.iterable.d.ts"],
  types: ["node"],
  typeRoots: [join(CHECK, "node_modules/@types")],
  jsx: ts.JsxEmit.ReactJSX,
  esModuleInterop: true,
  resolveJsonModule: true,
};

// Rule ids that v3/references/zod-3.md lists under "## No Zod 3 form": rows that start with a backticked id.
export function noV3Form(root: string): string[] {
  const ref = join(root, "v3/references/zod-3.md");
  if (!existsSync(ref)) return [];
  const section = /## No Zod 3 form\n([\s\S]*?)(?=\n## |$)/.exec(readFileSync(ref, "utf8"))?.[1] ?? "";
  return [...section.matchAll(/^\| `([a-z]+-[\w-]+)`/gm)].map((m) => m[1]);
}

export type Counts = { v4: number; v3: number; sameAsV3: number };

export function check(root: string): { findings: Finding[]; counts: Counts } {
  const composed: Composed[] = [];
  const counts: Counts = { v4: 0, v3: 0, sameAsV3: 0 };
  for (const src of markdownFiles(root)) {
    const blocks = extractBlocks(root, src);
    blocks.forEach((_, k) => composed.push(compose(blocks, k, composed.length)));
    counts[isV3(src) ? "v3" : "v4"] += blocks.length;
  }
  // The Zod 4 rules without a Zod 3 file, compiled a second time as Zod 3.
  if (existsSync(join(root, "v3/rules"))) {
    const exempt = new Set(noV3Form(root));
    for (const src of markdownFiles(root).filter((f) => f.startsWith("rules/"))) {
      const id = src.slice("rules/".length, -3);
      if (exempt.has(id) || existsSync(join(root, "v3/rules", `${id}.md`))) continue;
      const blocks = extractBlocks(root, src).map((b) => ({ ...b, v3: true, src: `${src} (as Zod 3)` }));
      blocks.forEach((_, k) => composed.push(compose(blocks, k, composed.length)));
      counts.sameAsV3 += blocks.length;
    }
  }
  const byFile = new Map(composed.map((c) => [c.file, c]));
  const ambient = ["prelude.d.ts", "modules.d.ts"].map((f) => join(CHECK, f)).filter((f) => existsSync(f));
  const roots = [...ambient, ...byFile.keys()];
  const stubs = join(CHECK, "stubs");
  const host: ts.LanguageServiceHost = {
    getScriptFileNames: () => roots,
    getScriptVersion: () => "1",
    getScriptSnapshot: (f) => {
      const c = byFile.get(f);
      if (c) return ts.ScriptSnapshot.fromString(c.text);
      return existsSync(f) ? ts.ScriptSnapshot.fromString(readFileSync(f, "utf8")) : undefined;
    },
    getCurrentDirectory: () => CHECK,
    getCompilationSettings: () => options,
    getDefaultLibFileName: (o) => ts.getDefaultLibFilePath(o),
    fileExists: (f) => byFile.has(f) || ts.sys.fileExists(f),
    readFile: (f) => byFile.get(f)?.text ?? ts.sys.readFile(f),
    readDirectory: ts.sys.readDirectory,
    directoryExists: ts.sys.directoryExists,
    getDirectories: ts.sys.getDirectories,
    // A relative import of an application module resolves to stubs/<path>.ts, which declares what the blocks import.
    // In a Zod 3 block, and in a stub under stubs/v3/, `zod` and `zod/<sub>` resolve to the `zod3` alias and its
    // subpaths; a Zod 3 block's relative import tries stubs/v3/<path>.ts before stubs/<path>.ts.
    resolveModuleNames: (names, containing) => {
      const v3 = byFile.get(containing)?.block.v3 ?? containing.startsWith(join(stubs, "v3") + "/");
      return names.map((name) => {
        const target = v3 && (name === "zod" || name.startsWith("zod/")) ? `zod3${name.slice(3)}` : name;
        const r = ts.resolveModuleName(target, containing, options, host as unknown as ts.ComputedModuleResolutionHost).resolvedModule;
        if (r || !name.startsWith(".")) return r;
        const rel = `${name.replace(/^(\.\.?\/)+/, "")}.ts`;
        const stub = (v3 ? [join(stubs, "v3", rel), join(stubs, rel)] : [join(stubs, rel)]).find((f) => existsSync(f));
        return stub ? { resolvedFileName: stub, extension: ts.Extension.Ts, isExternalLibraryImport: false } : undefined;
      });
    },
  };
  const service = ts.createLanguageService(host);
  const program = service.getProgram();
  if (!program) throw new Error("no program");
  const findings: Finding[] = [];
  for (const c of composed) {
    const sf = program.getSourceFile(c.file);
    if (!sf) throw new Error(`missing ${c.file}`);
    const bodyLines = c.block.body.split("\n");
    const lineOf = (pos: number) => sf.getLineAndCharacterOfPosition(pos).line - sf.getLineAndCharacterOfPosition(c.bodyStart).line;
    const inBody = (d: ts.Diagnostic) => d.start !== undefined && d.start >= c.bodyStart && d.start < c.bodyStart + c.block.body.length;
    const report = (rel: number, code: number | string, msg: string) =>
      findings.push({ src: c.block.src, line: c.block.line + rel, code, msg, text: (bodyLines[rel] ?? "").trim().slice(0, 140) });
    const errors = [...service.getSyntacticDiagnostics(c.file), ...service.getSemanticDiagnostics(c.file)];
    for (const d of errors) {
      if (!inBody(d)) continue;
      report(lineOf(d.start as number), d.code, ts.flattenDiagnosticMessageText(d.messageText, " ").slice(0, 240));
    }
    const deprecatedLines = new Set<number>();
    for (const d of service.getSuggestionDiagnostics(c.file)) {
      if (!d.reportsDeprecated || !inBody(d)) continue;
      const rel = lineOf(d.start as number);
      deprecatedLines.add(rel);
      if (!/\/\/\s*deprecated\b/i.test(bodyLines[rel] ?? ""))
        report(rel, "deprecated", ts.flattenDiagnosticMessageText(d.messageText, " ").slice(0, 240));
    }
    bodyLines.forEach((text, rel) => {
      if (/\/\/\s*deprecated\b/i.test(text) && !deprecatedLines.has(rel))
        report(rel, "marker", "line is marked deprecated but calls no deprecated API");
    });
  }
  return { findings: findings.sort((a, b) => a.src.localeCompare(b.src) || a.line - b.line), counts };
}

if (import.meta.main) {
  const { findings, counts } = check(ROOT);
  for (const f of findings) console.log(`${f.src}:${f.line}  ${typeof f.code === "number" ? `TS${f.code}` : f.code}  ${f.msg}\n    ${f.text}`);
  console.log(
    `${counts.v4 + counts.v3} blocks (${counts.v4} against zod 4, ${counts.v3} against zod 3, plus ${counts.sameAsV3} Zod 4 rule blocks compiled again as Zod 3), ${findings.length} findings`,
  );
  if (jsonOut) writeFileSync(jsonOut, JSON.stringify(findings, null, 1));
  process.exit(findings.length ? 1 : 0);
}
